const body = ($input.first().json.body) || {};

const userType = body.userType || body.role || 'citizen';
const language = body.language || 'en';
const query = body.query || body.message || body.prompt || body.text;

const validUserTypes = ['administrator', 'citizen', 'business'];
const validLanguages = ['en', 'hi', 'mr', 'en-in', 'hi-in', 'mr-in'];

const valid = Boolean(
  userType && language && query &&
  validUserTypes.includes(String(userType).toLowerCase())
);

const location = body.location || {};
const userId = body.userId || body.sessionId || body.user_id || 'session-' + String(userType).toLowerCase();

return [{
  json: {
    valid,
    userType: String(userType).toLowerCase(),
    language: String(language).toLowerCase(),
    query: String(query).trim(),
    userId: userId,
    sessionId: userId,
    location: {
      lat: location.lat ?? null,
      lng: location.lng ?? null,
      wardId: location.wardId ?? null,
    },
  },
}];

